"""Frozen cohort: fn_1_10A8D0 typed node/edge indexing instead of byte-offset carriers.

Families: (N) the three sort loops' `offset` node stride; (E) the in-half edge writes via
`edgeOffset`; (X) the cross-half edge writes via `inner`, plus the edge-count temporary.
Each family alone and combined, with node spellings &nodes[i]+1 / &nodes[i+1].
Stopping condition: these fixed variants once; actual profile; no flags/search.
"""
import sys, json, itertools
from pathlib import Path
sys.path.insert(0, 'tools')
from fzgx import api, fixup, oracle
from fzgx.project import Project
p = Project('GFZE01'); out = Path('.fzgx/manual-device-review/graph-index'); e = fixup.Engine(p, out)
key = 'main_rel:fn_1_10A8D0'; s = p.resolve(key); mw, flags = oracle.version_for(p, s)
body = api._canonical_text(p, p.unit_record(p.unit_of(s))['source'])
def must(t, old, new, n=1):
    assert t.count(old) == n, (old, t.count(old)); return t.replace(old, new)
def fam_n(t, spelling):
    t = must(t, '    struct { u32 value; } offset;\n', '')
    t = must(t, '    offset.value = i;\n    for (; i < g->nodeCount; offset.value += sizeof(Node_10A8D0), i++, a++) {\n',
               '    for (; i < g->nodeCount; i++, a++) {\n', 3)
    return must(t, '        b.value = (Node_10A8D0 *)((u8 *)g->nodes + offset.value) + 1;\n', f'        b.value = {spelling};\n', 3)
def fam_e(t):
    t = must(t, '    struct { u32 value; } edgeOffset;\n', '')
    t = must(t, '    i = 0;\n    edgeOffset.value = i;\n    k = 0;\n', '    i = 0;\n    k = 0;\n')
    t = must(t, '''            ((Edge_10A8D0 *)((u8 *)g->edges + edgeOffset.value))->a = a;
            ((Edge_10A8D0 *)((u8 *)g->edges + edgeOffset.value))->b = a + 1;
            ((Edge_10A8D0 *)((u8 *)g->edges + edgeOffset.value))->weight = fn_1_1289BC(a, a + 1);
            edgeOffset.value += sizeof(Edge_10A8D0);
            k++;
''', '''            g->edges[k].a = a;
            g->edges[k].b = a + 1;
            g->edges[k].weight = fn_1_1289BC(a, a + 1);
            k++;
''')
    return t
def fam_x(t):
    t = must(t, '    struct { u32 value; } inner;\n', '')
    t = must(t, '    inner.value = (half - 1) * 2;\n    g->edgeCount = inner.value + half;\n', '    g->edgeCount = (half - 1) * 2 + half;\n')
    t = must(t, '    inner.value = k * sizeof(Edge_10A8D0);\n', '')
    t = must(t, '''        ((Edge_10A8D0 *)((u8 *)g->edges + inner.value))->a = pairA.value;
        ((Edge_10A8D0 *)((u8 *)g->edges + inner.value))->b = c;
        ((Edge_10A8D0 *)((u8 *)g->edges + inner.value))->weight = fn_1_1289BC(pairA.value, c);
        inner.value += sizeof(Edge_10A8D0);
''', '''        g->edges[k].a = pairA.value;
        g->edges[k].b = c;
        g->edges[k].weight = fn_1_1289BC(pairA.value, c);
        k++;
''')
    return t
rows = [e.record(key, body, mw, flags, label='installed control')]
variants = []
for sp in ('&g->nodes[i] + 1', '&g->nodes[i + 1]'):
    variants.append((fam_n(body, sp), f'N {sp}'))
variants.append((fam_e(body), 'E'))
variants.append((fam_x(body), 'X'))
variants.append((fam_x(fam_e(body)), 'E+X'))
for sp in ('&g->nodes[i] + 1', '&g->nodes[i + 1]'):
    variants.append((fam_x(fam_e(fam_n(body, sp))), f'N {sp} + E + X'))
for t, l in variants:
    rows.append(e.record(key, t, mw, flags, parent=rows[0]['id'], label='typed indexing: ' + l))
with oracle.build_lock(): e.evaluate(rows)
report = dict(hypothesis=__doc__.strip(), stopping_condition='fixed variants once', records=rows, best={},
              frontier={'all_frozen_probes': rows}, generator_sha256=e.generator_sha256, environment=e.environment)
(out / 'report.json').write_text(json.dumps(report, indent=2) + '\n'); fixup.archive_sources(report, out / 'sources.json.gz')
for r in rows: print(r['sha256'][:12], bool(r.get('matched')), r.get('word_errors'), r.get('extra_helpers'), r['label'])

